(function () {
  var SEL = 'img[data-zurl]';
  var HINT = 1200;
  function load(im) {
    if (im.getAttribute('src-on')) return;
    im.setAttribute('src-on', '1');
    im.src = im.getAttribute('data-zurl');
  }
  function all() { return document.querySelectorAll(SEL); }
  var io = null;
  if ('IntersectionObserver' in window) {
    io = new IntersectionObserver(function (es) {
      for (var i = 0; i < es.length; i++) {
        if (es[i].isIntersecting) { load(es[i].target); io.unobserve(es[i].target); }
      }
    }, { rootMargin: HINT + 'px 0px' });
  }
  function bind() {
    var a = all();
    for (var i = 0; i < a.length; i++) {
      var im = a[i];
      if (im.getAttribute('bound-on')) continue;
      im.setAttribute('bound-on', '1');
      if (i < 3) load(im);            // 首屏前 3 张立即加载
      else if (io) io.observe(im);     // 其余视口懒加载
      else load(im);                   // 兜底：无 IO 就立即加载
    }
  }
  function sweep() {
    var a = all();
    for (var i = 0; i < a.length; i++) {
      var im = a[i];
      if (im.getBoundingClientRect().top < window.innerHeight + HINT) load(im);
    }
  }
  function total() { return all().length; }
  function loadedCount() {
    var a = all(), n = 0;
    for (var i = 0; i < a.length; i++) if (a[i].getAttribute('src-on')) n++;
    return n;
  }
  function run() {
    bind();
    setTimeout(bind, 400);
    setTimeout(bind, 1500);
    setTimeout(sweep, 6000);
    setTimeout(function () {                 // 兜底：20s 后一张都没加载 → 判定懒加载失效，全量立即加载
      if (total() > 0 && loadedCount() === 0) {
        var a = all();
        for (var i = 0; i < a.length; i++) load(a[i]);
      }
    }, 20000);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();

/* ===== 图片点击放大（强制中和 html/body transform；浮层 100vw/100vh + flex 双轴居中消除黑边；可点击图放宽到全部正文 img 支持 GIF 直链；未放大时左右/上下滑动切换上一张/下一张，到头循环） ===== */
(function () {
  var ov = null, ovImg = null, scale = 1, tx = 0, ty = 0, counter = null;
  var startDist = 0, startScale = 1, lastX = 0, lastY = 0;
  var swStartX = 0, swStartY = 0, moved = false, switched = false, wasZoomed = false;
  var MIN = 1, MAX = 6, SWIPE = 60;
  var SKIP = /smilie|emoji|avatar|icon|face|sign|ad-|button|logo|zoom-ov/i;
  var imgs = [], idx = 0;

  function neutralize(el) {
    if (!el) return;
    var cs = getComputedStyle(el);
    var props = ['transform', 'perspective', 'filter', 'willChange', 'contain'];
    el._zoomSaved = {};
    for (var i = 0; i < props.length; i++) {
      var p = props[i], comp = cs[p], inline = el.style[p], hit = false;
      if (p === 'willChange') { hit = comp && /transform|perspective|filter/.test(comp); }
      else if (p === 'contain') { hit = comp && /paint|layout|strict|content/.test(comp); }
      else { hit = comp && comp !== 'none'; }
      if (hit) { el._zoomSaved[p] = inline; el.style[p] = (p === 'willChange') ? 'auto' : 'none'; }
    }
  }
  function restore(el) {
    if (el && el._zoomSaved) {
      for (var p in el._zoomSaved) { el.style[p] = el._zoomSaved[p]; }
      el._zoomSaved = null;
    }
  }
  function apply() {
    if (!ovImg) return;
    ovImg.style.transform = 'translate(' + tx + 'px,' + ty + 'px) scale(' + scale + ')';
  }
  function dist(a, b) { return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY); }
  function reset() { scale = 1; tx = 0; ty = 0; apply(); }
  function closeZoom() {
    if (!ov) return;
    if (ov.parentNode) ov.parentNode.removeChild(ov);
    ov = null; ovImg = null; counter = null; scale = 1; tx = 0; ty = 0; imgs = []; idx = 0;
    restore(document.documentElement); restore(document.body);
  }
  function collect() {
    var a = document.querySelectorAll('img'), out = [];
    for (var i = 0; i < a.length; i++) {
      var im = a[i];
      if (im.getAttribute('zoom-ov')) continue;
      var cls = (im.getAttribute('class') || '') + ' ' + (im.className || '');
      if (SKIP.test(cls)) continue;
      var z = im.getAttribute('data-zurl');
      var s = im.getAttribute('src') || '';
      if (!z && s.indexOf('http') !== 0) continue;
      out.push(im);
    }
    return out;
  }
  function showImage(n) {
    if (!imgs.length) return;
    idx = ((n % imgs.length) + imgs.length) % imgs.length;
    var im = imgs[idx];
    var z = im.getAttribute('data-zurl');
    if (z && (!im.complete || !im.naturalWidth) && !im.getAttribute('src-on')) {
      im.src = z; im.setAttribute('src-on', '1');
    }
    ovImg.src = z || im.currentSrc || im.src || '';
    reset();
    if (counter) counter.textContent = (idx + 1) + ' / ' + imgs.length;
  }
  function openZoom(img) {
    if (ov) return;
    neutralize(document.documentElement); neutralize(document.body);
    imgs = collect(); idx = imgs.indexOf(img); if (idx < 0) idx = 0;
    ov = document.createElement('div');
    ov.className = 'zoom-ov';
    ov.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.95);z-index:2147483647;overflow:hidden;touch-action:none;-webkit-user-select:none;user-select:none;';
    ovImg = document.createElement('img');
    ovImg.setAttribute('zoom-ov', '1');
    ovImg.style.cssText = 'max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain;margin:0;padding:0;border:0;display:block;box-sizing:border-box;transform:scale(1);transform-origin:center center;will-change:transform;pointer-events:auto;touch-action:none;';
    ovImg.src = img.currentSrc || img.src || img.getAttribute('data-zurl') || '';
    ov.appendChild(ovImg);
    counter = document.createElement('div');
    counter.style.cssText = 'position:absolute;top:10px;left:12px;color:#fff;font-size:13px;opacity:.75;pointer-events:none;text-shadow:0 1px 2px #000;z-index:1;';
    counter.textContent = (idx + 1) + ' / ' + imgs.length;
    ov.appendChild(counter);
    ov.addEventListener('click', function (e) { if (e.target === ov) closeZoom(); });
    document.body.appendChild(ov);
    bindGestures();
    reset();
  }
  function bindGestures() {
    ovImg.style.cursor = 'zoom-out';
    ovImg.addEventListener('click', function (e) {
      e.stopPropagation();
      if (switched) { switched = false; return; }
      if (moved) { moved = false; return; }
      closeZoom();
    });
    ovImg.addEventListener('dblclick', function (e) {
      e.preventDefault(); e.stopPropagation();
      scale = (scale > 1.05) ? 1 : 2.6; tx = 0; ty = 0; apply();
    });
    ov.addEventListener('touchstart', function (e) {
      if (e.touches.length === 2) { startDist = dist(e.touches[0], e.touches[1]); startScale = scale; }
      else if (e.touches.length === 1) {
        lastX = swStartX = e.touches[0].clientX;
        lastY = swStartY = e.touches[0].clientY;
        moved = false; switched = false; wasZoomed = false;
      }
    }, { passive: false });
    ov.addEventListener('touchmove', function (e) {
      e.preventDefault();
      if (e.touches.length === 2 && startDist > 0) {
        var d = dist(e.touches[0], e.touches[1]);
        scale = Math.min(MAX, Math.max(MIN, startScale * d / startDist));
        if (scale > 1.05) wasZoomed = true;
        tx = 0; ty = 0; apply();
      } else if (e.touches.length === 1) {
        var nx = e.touches[0].clientX, ny = e.touches[0].clientY;
        var dx = nx - lastX, dy = ny - lastY;
        if (Math.abs(nx - swStartX) > 4 || Math.abs(ny - swStartY) > 4) moved = true;
        if (scale > 1.05) { tx += dx; ty += dy; apply(); wasZoomed = true; }
        lastX = nx; lastY = ny;
      }
    }, { passive: false });
    ov.addEventListener('touchend', function () {
      if (scale <= 1.05) {
        scale = 1; tx = 0; ty = 0; apply();
        if (!wasZoomed && moved) {
          var tdx = lastX - swStartX, tdy = lastY - swStartY;
          if (Math.abs(tdx) >= SWIPE || Math.abs(tdy) >= SWIPE) {
            if (Math.abs(tdx) >= Math.abs(tdy)) showImage(idx + (tdx < 0 ? 1 : -1));
            else showImage(idx + (tdy < 0 ? 1 : -1));
            switched = true;
          } else { moved = false; }
        }
      }
    });
  }
  function bindZoom() {
    var a = document.querySelectorAll('img');
    for (var i = 0; i < a.length; i++) {
      var im = a[i];
      if (im.getAttribute('zoom-on') || im.getAttribute('zoom-ov')) continue;
      var cls = (im.getAttribute('class') || '') + ' ' + (im.className || '');
      if (SKIP.test(cls)) continue;
      var zurl = im.getAttribute('data-zurl');
      var src0 = im.getAttribute('src') || '';
      if (!zurl && src0.indexOf('http') !== 0) continue;
      im.setAttribute('zoom-on', '1');
      im.style.cursor = 'zoom-in';
      im.addEventListener('click', function (e) {
        e.preventDefault();
        var z = this.getAttribute('data-zurl');
        if (z && (!this.complete || !this.naturalWidth) && !this.getAttribute('src-on')) {
          this.src = z; this.setAttribute('src-on', '1');
          return;
        }
        openZoom(this);
      });
    }
  }
  function runZoom() {
    bindZoom();
    if (window.MutationObserver) {
      var mo = new MutationObserver(function () { bindZoom(); });
      mo.observe(document.body, { childList: true, subtree: true });
    } else { setTimeout(runZoom, 1000); }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', runZoom);
  else runZoom();
})();

