/* 站址自动推导：优先取引擎传入的当前页 URL（换域后自动跟随），取不到才回落。
   ⇒ 换域只需改 sourceUrl 一处（header 已无域名依赖项），规则本身不用动。 */
var B = (function () {
  var u = (typeof baseUrl !== 'undefined' && baseUrl) ? String(baseUrl) : '';
  var m = u.match(/^https?:\/\/[^\/]+/);
  return m ? m[0] : 'https://hsnd.ubetl.com';
})();
/* 纳入范围的版块 fid：
     综合讨论区 95/166/141/142（143 求片问答悬赏区按用户要求去掉）
   ＋ 色花图片   155/125/50/48/49/117/165
   ＋ 原创BT电影 2/36/37/103/107/160/104/38/151/152/39（用户要求加入；
                 148 鲍鱼直播盒子除外 —— 外链版块，302 跳站外，站内无列表）
   导读页与搜索结果每行都带 forum-{fid}-1.html -> 按此过滤；
   版块页行内无 fid（实测集合为空）-> 一律保留，不会误杀。
   注意：色花文学整区（154/135/137/138/136/139）**永久排除**（CSAM 铁律），
   不在本白名单内 -> 首页/搜索里出现的文学区帖子会被自动过滤掉。 */
var FIDS = { '95': 1, '166': 1, '141': 1, '142': 1,
             '155': 1, '125': 1, '50': 1, '48': 1, '49': 1, '117': 1, '165': 1,
             '2': 1, '36': 1, '37': 1, '103': 1, '107': 1, '160': 1,
             '104': 1, '38': 1, '151': 1, '152': 1, '39': 1 };

/* ① 站务类 typeid —— 站方自己给帖子打的结构化分类，**精确排除、零误杀**。
   本站实测全站 50 个 typeid，绝大多数是内容分类（有码/无码/自拍/情色分享…），
   站务类只有这 3 个：662 版务 / 856 版务管理 / 830 版务管理。
   行内形态：<em>[<a href="forum.php?mod=forumdisplay&fid=95&filter=typeid&typeid=662">版务</a>]</em> */
var BAN_TYPEID = { '662': 1, '856': 1, '830': 1 };

/* ② 站务/公告类标题强词 —— 只用来兜「不带 typeid 的行」（首页导读 / 搜索结果）。
   🚫 刻意避开「必看 / 新人 / 管理 / 规则 / 活动 / 汇总 / 建议」等词：
   实测这些词会误杀真资源帖（[韩漫]猎艳管理员、足控必看、新人首贴、
   潜规则极品御姐、番号001-999汇总… 共 9 条），所以一个都不能进表。 */
var BAN_WORD = ['版规', '公告', '通知', '投诉', '举报', '版务', '招聘', '邀请码'];

/* ③ 置顶公告（<tbody id="stickthread_…">）本来就不会被收：采集正则只认
   normalthread_。本站 22 区共 165 条置顶（邀请码规则/高薪招聘/版规/投诉举报），
   因此 App 里从来不会出现。换站时务必确认该站置顶是否也用了 normalthread 前缀。 */

function _sid(h) {
  var s = String(h);
  var m = s.match(/safeid\s*=\s*'([^']+)'/);
  if (m) { return m[1]; }
  m = s.match(/safeid\s*=\s*"([^"]+)"/);
  return m ? m[1] : '';
}
function _abs(u) {
  u = String(u || '');
  if (u.indexOf('http') === 0) { return u; }
  if (!u) { return ''; }
  return B + (u.charAt(0) === '/' ? u : '/' + u);
}
/* 有内容（列表/搜索行） */
function _has(t) {
  t = String(t || '');
  return t.indexOf('normalthread_') >= 0 || t.indexOf('class="pbw"') >= 0;
}
/* 过门成功：拿到了任何"不是门页"的页（含站方提示信息页） */
function _open(t) {
  t = String(t || '');
  if (t.length < 200) { return false; }
  if (t.indexOf('safeid') >= 0 && t.length < 5000) { return false; }
  return true;
}
function _esc(s) {
  return String(s).replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
}
function _txt(h) {
  return _esc(String(h).replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').replace(/^ | $/g, '');
}
function _fidOf(seg) {
  var m = String(seg).match(/forum-(\d+)-1\.html/);
  return m ? m[1] : '';
}
function _keep(f) { return !f || !!FIDS[f]; }
/* 从一行里取标题文本（版块页 class="s xst"、导读页 class="xst"，实测每块恰好 1 个）。
   仅用于判定"是不是站务帖"，最终标题仍由 ruleTitle 的 a.xst 抽。 */
function _titleOf(seg) {
  var m = String(seg).match(/<a[^>]*class="(?:s\s+)?xst"[^>]*>([\s\S]*?)<\/a>/);
  return m ? _txt(m[1]) : '';
}
/* 非内容帖判据：站务 typeid（精确）优先，其次标题强词（兜底）。返回命中原因，''=正常帖 */
function _noise(seg, title) {
  var m = String(seg).match(/filter=typeid[^"]*?typeid=(\d+)/);
  if (m && BAN_TYPEID[m[1]]) { return 'typeid=' + m[1]; }
  if (!title) { return ''; }
  var i;
  for (i = 0; i < BAN_WORD.length; i++) {
    if (title.indexOf(BAN_WORD[i]) >= 0) { return BAN_WORD[i]; }
  }
  return '';
}
function _dateOf(seg) {
  var b = String(seg).match(/<td[^>]*class="by"[^>]*>[\s\S]*?<\/td>/);
  if (!b) { return ''; }
  var t = b[0].match(/title="(\d{4}-\d{1,2}-\d{1,2})"/);
  if (t) { return t[1]; }
  var e = b[0].match(/<em[^>]*>([\s\S]*?)<\/em>/);
  if (e) { return e[1].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim(); }
  return '';
}

function _row(tid, url, title, date) {
  return '<tbody id="normalthread_' + tid + '"><tr>'
    + '<td class="by"><em><span>' + (date || '-') + '</span></em><span class="sh-date">' + (date || '') + '</span></td>'
    + '<td class="new"><a class="xst" href="' + url + '">' + title + '</a></td>'
    + '</tr></tbody>';
}
function _msg(h) {
  var m = String(h).match(/id="messagetext"[\s\S]{0,900}?<p>([\s\S]*?)<\/p>/);
  return m ? _txt(m[1]) : '';
}

/* 自愈：依次尝试"能带自定义头"的联网方式。
   优先返回"拿到内容"的；若各路都只拿到"过门但无内容"的页（如站方节流提示页），
   也把它留下 —— 这样诊断行能回显站方原话，而不是误报成"通行证失效"。 */
function _heal(url, sid) {
  var hdr = { 'Cookie': '_safe=' + sid, 'Referer': B + '/' };
  var fails = [];
  var soft = { h: '', how: '' };
  var got;
  var take = function (h, p) {
    if (_has(h)) { return { h: h, how: p, fails: '' }; }
    if (!soft.h && _open(h)) { soft = { h: h, how: p + '(过门无内容)' }; }
    return null;
  };

  try { got = take(String(java.get(url, hdr) || ''), 'get-obj'); if (got) { return got; } } catch (e1) {}
  fails.push('get');

  try {
    var hm = new java.util.HashMap();
    hm.put('Cookie', '_safe=' + sid);
    hm.put('Referer', B + '/');
    got = take(String(java.get(url, hm) || ''), 'get-map');
    if (got) { return got; }
  } catch (e2) {}
  fails.push('getMap');

  try {
    if (typeof cookie !== 'undefined' && cookie && cookie.setCookie) {
      cookie.setCookie(B + '/', '_safe=' + sid);
    }
    got = take(String(java.ajax(url) || ''), 'cookieJar');
    if (got) { return got; }
  } catch (e3) {}
  fails.push('cookieJar');

  try {
    if (java.setCookie) { java.setCookie(B + '/', '_safe=' + sid); }
    got = take(String(java.ajax(url) || ''), 'setCookie');
    if (got) { return got; }
  } catch (e4) {}
  fails.push('setCookie');

  try {
    got = take(String(java.connect(url).header('Cookie', '_safe=' + sid)
      .header('Referer', B + '/').get() || ''), 'connect');
    if (got) { return got; }
  } catch (e5) {}
  fails.push('connect');

  try {
    got = take(String(java.webView(url, '') || ''), 'webview');
    if (got) { return got; }
  } catch (e6) {}
  fails.push('webview');

  if (soft.h) { return { h: soft.h, how: soft.how, fails: fails.join('/') }; }
  return { h: '', how: '', fails: fails.join('/') };
}

var html = String(result || '');
var isGate = (html.indexOf('safeid') >= 0 && html.length < 5000);
var healed = { h: '', how: '', fails: '' };

if (isGate) {
  var sid = _sid(html);
  var u = _abs(baseUrl);
  /* 只在 baseUrl 缺失时才兜底；绝不拿别的版块顶替。
     旧写法用 u.indexOf('forum-') 判断，而 'forum.php?...' 根本不含 'forum-'
     -> 首页撞门时会静默改取 forum-95 的列表（"首页显示综合讨论区"的真凶）。 */
  if (!u) { u = B + '/forum-95-1.html'; }
  if (sid) {
    healed = _heal(u, sid);
    if (_has(healed.h) || _open(healed.h)) { html = healed.h; }
  }
}

var OUT = [];
var i, seg, m, tid, url, title, dt;

/* A. 搜索结果页：li.pbw + h3.xs3（站内搜索用的是这个模板，不是 normalthread）
      每行都带 forum-{fid}-1.html 与 <span>日期</span> -> 可过滤、可取日期 */
if (html.indexOf('class="pbw"') >= 0) {
  var ps = html.split('<li class="pbw" id="');
  for (i = 1; i < ps.length; i++) {
    seg = ps[i].substring(0, 3000);
    tid = seg.split('"')[0];
    if (!/^\d+$/.test(tid)) { continue; }
    if (!_keep(_fidOf(seg))) { continue; }
    m = seg.match(/<h3[^>]*class="xs3"[^>]*>[\s\S]*?<a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/);
    if (!m) { continue; }
    url = _esc(m[1]);
    title = _txt(m[2]);
    if (!title) { continue; }
    if (_noise(seg, title)) { continue; }
    dt = seg.match(/<span>(\d{4}-\d{1,2}-\d{1,2}[^<]*)<\/span>/);
    OUT.push(_row(tid, url, title, dt ? dt[1] : ''));
  }
}

/* B. 论坛版块页 / 导读页：tbody#normalthread_
      标题锚点：版块页 class="s xst"、导读页 class="xst"
      -> 统一交给 ruleTitle/ruleLink 用 a.xst（两种都命中，且实测每块恰好 1 个） */
if (OUT.length === 0 && html.indexOf('normalthread_') >= 0) {
  var RE = /<tbody[^>]*id="normalthread_\d+"[\s\S]*?<\/tbody>/g;
  var M;
  while ((M = RE.exec(html)) !== null) {
    seg = M[0];
    if (!_keep(_fidOf(seg))) { continue; }
    if (_noise(seg, _titleOf(seg))) { continue; }
    var _dt = _dateOf(seg);
    if (_dt) { seg = seg.replace(/(<td class="by"[^>]*>[\s\S]*?<\/td>)/, '$1<span class="sh-date">' + _dt + '</span>'); }
    OUT.push(seg);

  }
}

/* C. 空列表 -> 一条可见诊断行（把站方原话与失败路径带到界面上，不再静默空白） */
if (OUT.length === 0) {
  var why = [];
  var sm = _msg(html);
  if (sm) {
    why.push('站方提示：' + sm);
  } else if (isGate) {
    why.push(healed.how
      ? ('通行证已换但仍无内容(' + healed.how + ')')
      : ('通行证失效，自愈未成功：' + (healed.fails || '无')));
  }
  if (!why.length) { why.push('列表解析为空（既无 normalthread 也无 pbw）'); }
  if (sm && (sm.indexOf('不能少于') >= 0 || sm.indexOf('关键字') >= 0)) {
    why.push('「搜索」标签须先在源编辑里填「变量」；或改用顶部搜索框输词');
  }
  OUT.push(_row('0', _abs(baseUrl) || (B + '/forum-95-1.html'),
    '⚠️ ' + why.join('；') + ' ─ 点此打开原页', '-'));
}

result = OUT;

ruleContent:
@js:
/* 站址自动推导：优先取引擎传入的当前页 URL（换域后自动跟随），取不到才回落。
   ⇒ 换域只需改 sourceUrl 一处（header 已无域名依赖项），规则本身不用动。 */
var B = (function () {
  var u = (typeof baseUrl !== 'undefined' && baseUrl) ? String(baseUrl) : '';
  var m = u.match(/^https?:\/\/[^\/]+/);
  return m ? m[0] : 'https://hsnd.ubetl.com';
})();
var MARK = 'postmessage_';
var WRAP_CSS = '<style>*{box-sizing:border-box!important;max-width:100%!important}html,body{overflow-x:hidden!important}body{font-size:17px;line-height:1.8;word-break:break-word!important;overflow-wrap:break-word!important;white-space:normal!important}div,p,span,font,td,th,li,article,section,blockquote,a,h1,h2,h3,h4{word-break:break-word!important;overflow-wrap:break-word!important;white-space:normal!important}pre,code{white-space:pre-wrap!important;word-break:break-word!important}table{border-collapse:collapse!important;table-layout:fixed!important;width:100%!important}img,video,.sh-img{max-width:100%!important;height:auto!important;display:block;margin:8px auto}</style>';

function _ok(t) { return !!t && String(t).indexOf(MARK) >= 0; }
function _abs(u) {
  u = String(u || '');
  if (u.indexOf('http') === 0) return u;
  if (!u) return '';
  return B + (u.charAt(0) === '/' ? u : '/' + u);
}

/* 与列表规则同款多路自愈（marker 换成 postmessage_） */
function _heal(url, sid) {
  var hdr = { 'Cookie': '_safe=' + sid, 'Referer': B + '/' };
  var fails = [];
  var t;

  try { t = String(java.get(url, hdr) || ''); if (_ok(t)) return { h: t, how: 'get-obj' }; } catch (e1) {}
  fails.push('get');

  try {
    var hm = new java.util.HashMap();
    hm.put('Cookie', '_safe=' + sid);
    hm.put('Referer', B + '/');
    t = String(java.get(url, hm) || '');
    if (_ok(t)) return { h: t, how: 'get-map' };
  } catch (e2) {}
  fails.push('getMap');

  try {
    if (typeof cookie !== 'undefined' && cookie && cookie.setCookie) {
      cookie.setCookie(B + '/', '_safe=' + sid);
    }
    t = String(java.ajax(url) || '');
    if (_ok(t)) return { h: t, how: 'cookieJar' };
  } catch (e3) {}
  fails.push('cookieJar');

  try {
    if (java.setCookie) { java.setCookie(B + '/', '_safe=' + sid); }
    t = String(java.ajax(url) || '');
    if (_ok(t)) return { h: t, how: 'setCookie' };
  } catch (e4) {}
  fails.push('setCookie');

  try {
    t = String(java.connect(url).header('Cookie', '_safe=' + sid)
               .header('Referer', B + '/').get() || '');
    if (_ok(t)) return { h: t, how: 'connect' };
  } catch (e5) {}
  fails.push('connect');

  try {
    t = String(java.webView(url, '') || '');
    if (_ok(t)) return { h: t, how: 'webview' };
  } catch (e6) {}
  fails.push('webview');

  return { h: '', how: '', fails: fails.join('/') };
}

var html = String(result || '');
var isGate = (html.indexOf('safeid') >= 0 && html.length < 5000);
var diag = '';

if (isGate) {
  var sid = (html.match(/safeid\s*=\s*'([^']+)'/) || [])[1] || '';
  var u = _abs(baseUrl);
  if (sid && u) {
    var r = _heal(u, sid);
    if (_ok(r.h)) { html = r.h; } else { diag = '正文通行证失效，自愈均未成功（' + r.fails + '）'; }
  } else {
    diag = '正文撞门但取不到 safeid 或 baseUrl';
  }
}

if (!_ok(html)) {
  if (!diag) { diag = '正文解析为空（未命中 postmessage）'; }
  result = '<p style="font-size:18px;line-height:1.9;color:#c0392b">⚠️ ' + diag + '</p>';
} else {
  /* —— 切片：必须连 <td …> 一起吃掉，否则首行残留 id="…"> 脏字 —— */
  /* 首帖正文块：<td> 与 <div> 的 postmessage_ 都认（AI专区 图为 div 渲染），取含图最多/有实质内容的一块；
     回退分支也切到 id= 之后，避免顶部泄漏 id="postmessage_…" 脏字 */
  var PATT = /(?:<t[dh]|<div)[^>]*id="postmessage_\d+"[^>]*>/g;
  var cand = null, best = -1, _mm;
  while ((_mm = PATT.exec(html)) !== null) {
    var _s = _mm.index + _mm[0].length;
    var _e = html.indexOf('id="postmessage_', _s);
    var _seg = _e > _s ? html.slice(_s, _e) : html.slice(_s);
    var _score = (_seg.match(/ignore_js_op/g) || []).length
               + (_seg.replace(/<[^>]*>/g, ' ').trim().length > 30 ? 1 : 0);
    if (_score > best) { best = _score; cand = _mm; }
  }
  if (cand) {
    html = html.slice(cand.index + cand[0].length);
  } else {
    var m2 = html.match(/id="postmessage_\d+"/);
    if (m2) { html = html.slice(html.indexOf(m2[0]) + m2[0].length); }
  }
  var terms = ['id="comment_', '<div class="authi"', '<div class="pct"'];
  var cut = html.length;
  for (var i = 0; i < terms.length; i++) {
    var p = html.indexOf(terms[i]);
    if (p > 0 && p < cut) { cut = p; }
  }
  html = html.slice(0, cut);

  /* 附件区 <ignore_js_op> → 懒加载占位图（file= 与 zoomfile= 同 URL） */
  html = html.replace(/<ignore_js_op>[\s\S]*?<\/ignore_js_op>/g, function (blk) {
    var u2 = blk.match(/(?:zoomfile|file)="([^"]+)"/);
    if (!u2) return '';
    return '<img class="sh-img" data-zurl="' + u2[1] + '" />';
  });
  html = html.replace(/<img[^>]*none\.gif[^>]*\/?>/g, '');
  html = html.replace(/<i class="pstatus">[\s\S]*?<\/i>/g, '');

  /* 外链/远程图片：Discuz 的 <img class="zoom" file="https://..."/> 无真实 src 形态（写真/外链图床常见，如图床 b23.pic2607v.cc），浏览器看不到 src 故不显示；补成 src + data-zurl 交给懒加载器（injectJs 只认 img[data-zurl]）。已处理过的 sh-img/data-zurl 图直接跳过，避免重复。 */
  html = html.replace(/<img\b[^>]*>/gi, function (m) {
    if (m.indexOf('data-zurl=') >= 0 || m.indexOf('sh-img') >= 0) return m;
    var f = m.match(/\bfile="(https?:\/\/[^\"]+)"/);
    if (!f) return m;
    var url = f[1];
    var out = m;
    if (/class="/.test(out)) out = out.replace(/class="([^"]*)"/, 'class="$1 sh-img"');
    else out = out.replace(/<img\b/, '<img class="sh-img"');
    if (/src="https?:\/\//.test(out)) {
      out = out.replace(/(\/?>)\s*$/, ' data-zurl="' + url + '"$1');
    } else {
      out = '<img class="sh-img" src="' + url + '" data-zurl="' + url + '" />';
    }
    return out;
  });
  /* 清理残留的 torrent 附件图标（无真实图），避免裂图 */
  html = html.replace(/<img[^>]*filetype\/torrent\.gif[^>]*\/?>/gi, '');

  result = WRAP_CSS + html;
}
